import { Column, Entity, Index, PrimaryGeneratedColumn } from 'typeorm';

/** The stored states of an issue. */
export type IssueState = 'open' | 'closed';

/**
 * A Kerghan issue of a project. Owns table `issues` (see
 * `docs/agents/modules/issues/data-model.md#issues-kerghan-issues`). It has no `user_id`: access goes
 * through the project. `projectId` is a logical FK only. `updatedAt` is `datetime(3)`, written
 * from the injected `Clock`. `uuid` is generated by the service at insert.
 */
@Entity('issues')
@Index('idx_issues_uuid', ['uuid'], { unique: true })
@Index('idx_issues_project_id_state_created_at', ['projectId', 'state', 'createdAt'])
export class Issue {
  @PrimaryGeneratedColumn()
    id!: number;

  @Column({ type: 'char', length: 36 })
    uuid!: string;

  @Column({ name: 'project_id', type: 'int' })
    projectId!: number;

  @Column({ type: 'varchar', length: 256 })
    title!: string;

  @Column({ type: 'mediumtext', nullable: true })
    body!: string | null;

  @Column({ type: 'varchar', length: 16, default: 'open' })
    state!: IssueState;

  @Column({ name: 'created_at', type: 'datetime' })
    createdAt!: Date;

  @Column({ name: 'updated_at', type: 'datetime', precision: 3 })
    updatedAt!: Date;
}
